UPDATE candidate_interview_availability
SET timezone = #{availability.timezone},
    ranges_json = CAST(#{availability.rangesJson} AS JSONB),
    version = version + 1,
    updated_by = #{availability.updatedBy},
    trace_id = #{availability.traceId},
    updated_at = #{availability.updatedAt}
WHERE candidate_user_id = #{availability.candidateUserId}
  AND version = #{expectedVersion}
